'use strict';
const $=id=>document.getElementById(id), canvas=$('canvas'), ctx=canvas.getContext('2d');
const IS_BALAC=typeof window!=='undefined'&&window.CIDA_STUDIO_VARIANT==='balac',DRAFT_KEY=IS_BALAC?'balac-promo-drafts':'cida-promo-drafts';
const fields=['title','brand','mode','description','bundles','discount','buyQty','freeQty','gift','color','format','date','tax','footer'];
let products=IS_BALAC?[{code:'XONEF030',qty:1,price:22.69}]:[{code:'XONTA064',qty:1,price:7.58}], images={}, sources={}, base=new Image(), drafts=[];
const euro=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(n);
const clamp=(v,min,max)=>Math.min(max,Math.max(min,Number(v)||0));
function quantityOffer(){return {buy:Math.floor(clamp($('buyQty').value,1,999)),free:Math.floor(clamp($('freeQty').value,1,999))};}
function quantityPromoPrice(price){const q=quantityOffer();return Math.round((clamp(price,0,1e9)*q.buy/(q.buy+q.free)+Number.EPSILON)*100)/100;}
function totals(){const single=products.reduce((a,p)=>a+Math.round(clamp(p.price,0,1e9)*100)*clamp(p.qty,1,999),0)/100;const multiplier=$('mode').value==='quantity'?quantityOffer().buy:1;const original=Math.round(single*multiplier*clamp($('bundles').value,1,999)*100)/100;const final=$('mode').value==='discount'?Math.round(original*(1-clamp($('discount').value,0,100)/100)*100)/100:original;return{single,original,final};}
function toast(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3200)}
function rows(){const box=$('rows');box.replaceChildren();products.forEach((p,i)=>{const r=document.createElement('div');r.className='product';for(const k of ['code','qty','price']){const input=document.createElement('input');input.value=p[k];input.setAttribute('aria-label',k==='code'?'Codice o descrizione prodotto':k==='qty'?'Quantità':'Prezzo unitario');if(k==='code')input.maxLength=55;else{input.type='number';input.min=k==='qty'?'1':'0';input.max=k==='qty'?'999':'1000000000';input.step=k==='qty'?'1':'0.01'}input.addEventListener('input',()=>{products[i][k]=k==='code'?input.value:clamp(input.value,k==='qty'?1:0,k==='qty'?999:1e9);render()});r.append(input)}const b=document.createElement('button');b.textContent='×';b.setAttribute('aria-label','Rimuovi prodotto');b.onclick=()=>{products.splice(i,1);rows();render()};r.append(b);box.append(r)});$('add').disabled=products.length>=8;}
function text(t,x,y,size=36,color='#000',weight='normal',max=830){t=String(t);ctx.fillStyle=color;ctx.textAlign='left';let s=size;do{ctx.font=`${weight} ${s}px Arial`;if(ctx.measureText(t).width<=max)break;s--}while(s>12);ctx.fillText(t,x,y);}
function wrap(t,x,y,size,maxWidth,lineHeight,maxLines=3,color='#000',weight='normal'){ctx.font=`${weight} ${size}px Arial`;const words=String(t).split(/\s+/),lines=[];let line='';for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);if(lines.length>maxLines){return wrap(t,x,y,size-2,maxWidth,lineHeight-2,maxLines,color,weight)}lines.forEach((l,i)=>text(l,x,y+i*lineHeight,size,color,weight,maxWidth));return lines.length*lineHeight;}
function contain(img,x,y,w,h){const s=Math.min(w/img.width,h/img.height);ctx.drawImage(img,x+(w-img.width*s)/2,y+(h-img.height*s)/2,img.width*s,img.height*s)}
function render(){if(!base.complete||!base.naturalWidth)return;if(IS_BALAC){renderBalac();updateSummary();if(window.CidaStudioRendered)window.CidaStudioRendered();return;}canvas.width=1080;canvas.height=1080;ctx.drawImage(base,0,0,1080,1080);ctx.fillStyle='#fff';ctx.fillRect(122,250,934,313);ctx.fillRect(252,572,600,388);ctx.fillRect(633,104,285,122);
if(images.logo){ctx.fillStyle='#fff';ctx.fillRect(12,14,493,153);contain(images.logo,25,20,480,145)}
if(images.brandlogo)contain(images.brandlogo,635,108,280,112);else text($('brand').value,654,175,45,'#222','bold',250);
const t=totals(),accent=$('color').value,mode=$('mode').value,webOnly=mode==='none';let title=$('title').value.toUpperCase();const extra=mode==='discount'?`EXTRA ${clamp($('discount').value,0,100)}%`:mode==='gift'?'CON OMAGGIO':mode==='quantity'?`${quantityOffer().buy}+${quantityOffer().free} OMAGGIO`:webOnly?'':'PREZZO SPECIALE';let headingSize=39;const headingGap=extra?18:0;do{ctx.font=`bold ${headingSize}px Arial`;if(ctx.measureText(title).width+headingGap+ctx.measureText(extra).width<=890)break;headingSize--;}while(headingSize>12);const titleWidth=ctx.measureText(title).width;text(title,130,296,headingSize,'#000','bold',890);if(extra)text(extra,130+titleWidth+headingGap,296,headingSize,accent,'bold',890-titleWidth-headingGap);
const descH=wrap($('description').value.toUpperCase(),130,350,40,850,47,2);
let y=350+descH+12;
if(products.length===1){text('COD.',130,y,40,'#000','bold',110);text(products[0].code.toUpperCase(),250,y,40,accent,'bold',700);if(products[0].qty>1||clamp($('bundles').value,1,999)>1){y+=32;text(`${products[0].qty} pz × ${clamp($('bundles').value,1,999)} pacchetto/i`,130,y,23,'#333','bold',840)}}
else{const rowH=products.length>5?25:30;products.forEach((p,i)=>text(`${p.code.toUpperCase()}   •   ${p.qty} PZ${mode==='quantity'?'   •   '+euro(quantityPromoPrice(p.price))+' / PZ':''}`,130,y+i*rowH,products.length>5?21:25,'#222','bold',800));y+=Math.max(0,products.length-1)*rowH;}
if(mode==='quantity'){const q=quantityOffer();y+=34;text(`ACQUISTI ${q.buy} + ${q.free} IN OMAGGIO`,130,y,28,accent,'bold',850);}
y+=18;
const priceY=Math.min(y,720), label=mode==='quantity'?(products.length===1?euro(quantityPromoPrice(products[0].price)):'PREZZI UNITARI'):mode==='gift'?euro(t.final):t.original!==t.final?`${euro(t.original)} → ${euro(t.final)}`:euro(t.final);ctx.font='bold 43px Arial';const pw=Math.min(800,ctx.measureText(label).width+24);ctx.save();ctx.shadowColor='#0006';ctx.shadowBlur=9;ctx.shadowOffsetY=6;ctx.fillStyle=accent;ctx.beginPath();ctx.moveTo(130,priceY);ctx.lineTo(130+pw,priceY);ctx.lineTo(130+pw+35,priceY+25);ctx.lineTo(130+pw,priceY+50);ctx.lineTo(130,priceY+50);ctx.closePath();ctx.fill();ctx.restore();text(label,140,priceY+40,43,'#fff','bold',pw-10);text(mode==='quantity'?'NETTO PROMO':$('tax').value.toUpperCase(),130,priceY+89,31,accent,'bold',800);
let photoTop=Math.max(590,priceY+110);if(mode==='gift'&&$('gift').value){text($('gift').value.toUpperCase(),130,photoTop,29,accent,'bold',850);photoTop+=35}const photoHeight=Math.max(120,946-photoTop);if(images.photo)contain(images.photo,270,photoTop,560,photoHeight);else{ctx.save();ctx.strokeStyle='#ddd';ctx.setLineDash([10,8]);ctx.strokeRect(315,photoTop+10,450,photoHeight-30);ctx.restore();text('CARICA LA FOTO DEL PRODOTTO',345,photoTop+photoHeight/2,20,'#bbb','normal',390)}
if($('date').value){ctx.fillStyle='#fff';ctx.fillRect(270,946,560,27);text($('date').value,280,966,19,'#444','normal',540)}
// Keep the reference footer when unchanged; custom footer retains its blue band.
const footerText=$('footer').value;
if(footerText!=='PROMO AUTOMATICAMENTE INSERITA A WEB'){ctx.fillStyle='#064c87';ctx.fillRect(204,984,805,72);text(footerText.toUpperCase(),224,1030,32,'#fff','bold',760)}
updateSummary();}
function updateSummary(){const t=totals(),mode=$('mode').value;$('sum').textContent=mode==='quantity'?(products.length===1?euro(quantityPromoPrice(products[0].price)):'Vedi prezzi per prodotto'):euro(t.final);$('summaryLabel').textContent=mode==='quantity'?'Netto promo unitario':'Totale promozionale';$('giftLabel').hidden=mode!=='gift';$('discountLabel').hidden=mode!=='discount';$('quantityFields').hidden=mode!=='quantity';if(mode==='quantity'){const q=quantityOffer();$('quantitySummary').textContent=products.map(p=>`${p.code||'Prodotto'}: ${euro(p.price)} × ${q.buy} ÷ ${q.buy+q.free} = ${euro(quantityPromoPrice(p.price))} netto promo.`).join(' ');}}
function snapshot(){const data={version:1,variant:IS_BALAC?'balac':'cida',fields:{},products:products.map(p=>({...p})),images:{...sources}};fields.forEach(f=>data.fields[f]=$(f).value);return data;}
async function restore(data){if(data&&data.variant&&data.variant!==(IS_BALAC?'balac':'cida'))throw Error('Questo progetto appartiene alla sezione '+data.variant.toUpperCase());if(!data||data.version!==1||!data.fields||!Array.isArray(data.products)||data.products.length>8)throw Error('Progetto non valido');fields.forEach(f=>{if(typeof data.fields[f]==='string')$(f).value=data.fields[f];else if(f==='buyQty')$(f).value='10';else if(f==='freeQty')$(f).value='1'});products=data.products.map(p=>({code:String(p.code||'').slice(0,55),qty:clamp(p.qty,1,999),price:clamp(p.price,0,1e9)}));images={};sources={};for(const key of ['logo','photo','brandlogo']){const src=data.images?.[key];if(typeof src==='string'&&src.startsWith('data:image/')&&src.length<12000000){images[key]=await imageFrom(src);sources[key]=src}}rows();render();}
function imageFrom(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Immagine non leggibile'));img.src=src})}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function filename(){return ((IS_BALAC?'BALAC_':'CIDA_')+($('title').value||'Promo')).replace(/[^a-z0-9àèéìòù_-]+/gi,'_')}
for(const f of fields)$(f).addEventListener('input',render);
$('add').onclick=()=>{if(products.length<8){products.push({code:'',qty:1,price:0});rows();render()}};
for(const key of ['logo','photo','brandlogo'])$(key).onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>8000000){toast('Scegli un’immagine inferiore a 8 MB');return}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const img=await imageFrom(src);const c=document.createElement('canvas');const factor=Math.min(1,1600/Math.max(img.width,img.height));c.width=Math.round(img.width*factor);c.height=Math.round(img.height*factor);c.getContext('2d').drawImage(img,0,0,c.width,c.height);sources[key]=c.toDataURL('image/png');images[key]=await imageFrom(sources[key]);render();toast('Immagine caricata')}catch{toast('Impossibile aprire questa immagine')}};
$('clearImages').onclick=()=>{images={};sources={};for(const k of ['logo','photo','brandlogo'])$(k).value='';render()};
for(const kind of ['png','jpg'])$(kind).onclick=()=>{render();canvas.toBlob(b=>{if(b){download(b,filename()+'.'+kind);toast('Locandina scaricata')}},kind==='png'?'image/png':'image/jpeg',.96)};
$('print').onclick=()=>{render();const win=window.open('','_blank');if(!win){toast('Consenti le finestre popup per stampare');return}win.document.write('<!doctype html><html><head><title>Locandina CIDA</title><style>@page{size:A4;margin:12mm}body{margin:0}img{width:100%;height:auto}</style></head><body><img alt="Locandina CIDA"></body></html>');win.document.close();const img=win.document.querySelector('img');img.onload=()=>{win.focus();win.print()};img.src=canvas.toDataURL('image/png')};
function populate(){const sel=$('drafts');sel.replaceChildren(new Option('Seleziona una bozza salvata',''));drafts.forEach(d=>sel.add(new Option(d.name,d.id)))}
try{const stored=JSON.parse(localStorage.getItem(DRAFT_KEY)||'[]');if(Array.isArray(stored))drafts=stored}catch{}
function persist(){try{localStorage.setItem(DRAFT_KEY,JSON.stringify(drafts));populate();return true}catch{toast('Spazio browser esaurito: esporta il progetto');return false}}
$('save').onclick=()=>{const id=Date.now().toString();const d={id,name:$('title').value+' · '+new Date().toLocaleDateString('it-IT'),data:snapshot()};drafts.push(d);if(persist()){ $('drafts').value=id;toast('Bozza salvata')}else drafts.pop()};
$('load').onclick=async()=>{const d=drafts.find(d=>d.id===$('drafts').value);if(!d){toast('Seleziona una bozza');return}try{await restore(d.data);toast('Bozza aperta')}catch{toast('Impossibile aprire la bozza')}};
$('delete').onclick=()=>{const id=$('drafts').value;if(!id){toast('Seleziona una bozza');return}drafts=drafts.filter(d=>d.id!==id);persist();toast('Bozza eliminata')};
$('export').onclick=()=>download(new Blob([JSON.stringify(snapshot(),null,2)],{type:'application/json'}),filename()+'.json');
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>30000000){toast('Progetto troppo grande');return}try{await restore(JSON.parse(await f.text()));toast('Progetto importato')}catch{toast('File progetto non valido')}e.target.value=''};
const defaults=snapshot();$('new').onclick=async()=>{await restore(defaults);toast('Nuova promo pronta')};
base.onload=()=>{rows();populate();render()};base.onerror=()=>toast('Il modello non è disponibile. Ricarica la pagina.');base.src=IS_BALAC?'balac-template.jpg':'template.jpg';
